repo_root <- normalizePath(file.path(testthat::test_path(), "..", "..", ".."), winslash = "/", mustWork = TRUE)
source(file.path(repo_root, "operator_hypothesis_lab", "R", "hyp_intraday_momentum_engine.R"))
source(file.path(repo_root, "operator_hypothesis_lab", "R", "hyp_reg_01_2_strategy_overlay.R"))
source(file.path(repo_root, "operator_hypothesis_lab", "R", "hyp_reg_09_1_robust_slope_fit_poc.R"))
source(file.path(repo_root, "operator_hypothesis_lab", "R", "hyp_reg_12_1_range_persistence_poc.R"))

hreg121_test_bars <- function(close) { dates <- seq(as.Date("2020-01-02"), by = "day", length.out = length(close)); data.frame(symbol = "TEST", session_date = dates, timestamp_utc = as.POSIXct(dates, tz = "UTC"), open = close, high = close * 1.01, low = close * .99, close = close, volume = 1000) }

testthat::test_that("contract freezes one contextual range lane", { x <- hreg121_contract(); testthat::expect_equal(x$hypothesis_id, "HYP-REG-12.1"); testthat::expect_equal(x$range_window, 63L); testthat::expect_equal(x$upper_threshold, .75); testthat::expect_equal(x$persistence_required, 3L); testthat::expect_equal(x$confirmation_start, as.Date("2024-01-02")) })
testthat::test_that("range position excludes the current close from its boundary", { x <- hreg121_range_position(1:70, 63); testthat::expect_equal(x$prior_high[[64]], 63); testthat::expect_gt(x$range_position[[64]], 1) })
testthat::test_that("range position remains uncapped", { close <- c(seq(10, 20, length.out = 63), 30); testthat::expect_gt(tail(hreg121_range_position(close, 63)$range_position, 1), 1) })
testthat::test_that("three of five upper observations require the current observation", { c <- hreg121_contract(); rp <- c(rep(NA, 63), .8, .8, .2, .8, .2, .8); p <- hreg121_persistence(rp, c); testthat::expect_false(p$upper_persistent[[68]]); testthat::expect_true(p$upper_persistent[[69]]) })
testthat::test_that("lower persistence is symmetric", { rp <- c(rep(NA, 63), .2, .2, .8, .2, .8, .2); p <- hreg121_persistence(rp); testthat::expect_true(tail(p$lower_persistent, 1)) })
testthat::test_that("breakout boundary is fixed and event does not extend", { c <- hreg121_contract(); close <- c(seq(10, 20, length.out = 63), 21, 22, 23, rep(24, 12)); l <- hreg121_build_asset_ledger(hreg121_test_bars(close), c); active <- which(l$breakout_event_active); testthat::expect_equal(length(active), c$event_sessions); testthat::expect_equal(length(unique(l$breakout_boundary[active])), 1L); testthat::expect_equal(l$breakout_age[active], 0:(c$event_sessions - 1L)) })
testthat::test_that("retests count only crossings from above", { close <- c(seq(10, 20, length.out = 63), 21, 19, 21, 19, rep(19, 8)); l <- hreg121_build_asset_ledger(hreg121_test_bars(close)); testthat::expect_equal(max(l$breakout_retests_so_far, na.rm = TRUE), 2L) })
testthat::test_that("completed events use a ten-session fixed path", { close <- c(seq(10, 20, length.out = 63), 21, rep(22, 12)); l <- hreg121_build_asset_ledger(hreg121_test_bars(close)); o <- hreg121_event_outcomes(l); testthat::expect_equal(o$sessions[[1]], 10L); testthat::expect_true(o$terminal_above[[1]]) })
testthat::test_that("synthetic hold and rapid-failure fixtures express their labels", { set.seed(1); hold <- exp(hreg121_simulate_log_path("BREAKOUT_HOLD")); fail <- exp(hreg121_simulate_log_path("BREAKOUT_FAIL")); oh <- tail(hreg121_event_outcomes(hreg121_build_asset_ledger(hreg121_test_bars(hold))), 1L); of <- tail(hreg121_event_outcomes(hreg121_build_asset_ledger(hreg121_test_bars(fail))), 1L); testthat::expect_true(oh$terminal_above[[1]]); testthat::expect_true(of$rapid_failure[[1]]) })
testthat::test_that("price scale does not change the measurement", { close <- exp(cumsum(rep(.002, 150))); a <- hreg121_build_asset_ledger(hreg121_test_bars(close)); b <- hreg121_build_asset_ledger(hreg121_test_bars(close * 7)); testthat::expect_equal(a$range_position, b$range_position, tolerance = 1e-12); testthat::expect_equal(a$range_state, b$range_state) })
testthat::test_that("append audit is exactly causal", { testthat::expect_true(all(hreg121_causality_audit()$passed)) })
testthat::test_that("confirmation and duplicate rows are rejected", { bars <- hreg121_test_bars(seq(10, 20, length.out = 150)); bars$session_date <- seq(as.Date("2023-11-01"), by = "day", length.out = nrow(bars)); testthat::expect_error(hreg91_assert_bars(bars, hreg121_contract()), "Confirmation"); bars <- hreg121_test_bars(seq(10, 20, length.out = 150)); testthat::expect_error(hreg91_assert_bars(rbind(bars, bars[1, ]), hreg121_contract()), "duplicated") })
testthat::test_that("entry policy skips rejected crosses rather than deferring", { bars <- hreg121_test_bars(exp(cumsum(sin(seq_len(180) / 4) * .02))); frame <- hreg121_align(hreg12_cross_frame(bars), hreg121_build_asset_ledger(bars)); cross <- which(frame$cross_up & seq_len(nrow(frame)) > 70)[1L]; frame$upper_persistent[] <- FALSE; schedule <- hreg121_schedule(frame, min(frame$session_date), max(frame$session_date), "ENTRY_UPPER_PERSISTENT_ONLY"); testthat::expect_true(schedule$blocked_entry[[cross + 1L]]); testthat::expect_false(schedule$target[[cross + 1L]]) })
testthat::test_that("unfiltered and fully eligible schedules agree", { bars <- hreg121_test_bars(exp(cumsum(sin(seq_len(180) / 4) * .02))); frame <- hreg121_align(hreg12_cross_frame(bars), hreg121_build_asset_ledger(bars)); a <- hreg121_schedule(frame, min(frame$session_date), max(frame$session_date), "UNFILTERED"); frame$upper_persistent[] <- TRUE; b <- hreg121_schedule(frame, min(frame$session_date), max(frame$session_date), "ENTRY_UPPER_PERSISTENT_ONLY"); testthat::expect_equal(a$target, b$target) })
testthat::test_that("circular controls are deterministic and nonzero", { bars <- hreg121_test_bars(exp(cumsum(sin(seq_len(180) / 4) * .02))); frame <- hreg121_align(hreg12_cross_frame(bars), hreg121_build_asset_ledger(bars)); a <- hreg121_shifted_schedule(frame, min(frame$session_date), max(frame$session_date), 7); b <- hreg121_shifted_schedule(frame, min(frame$session_date), max(frame$session_date), 7); testthat::expect_equal(a$target, b$target); testthat::expect_gt(attr(a, "shift_offset"), 0) })
testthat::test_that("exposure-nearest selection ignores returns", { x <- data.frame(simulation_id = 1:4, median_exposure = c(.1, .2, .3, .4), median_return = c(100, -100, 50, 0)); testthat::expect_equal(hreg121_exposure_near_ids(x, .26, 2), c(3L, 2L)) })
